import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion'; // Important pour le feeling "smooth"
import { Search, User, Menu, ArrowRight, Star, Globe, BookOpen, MessageCircle } from 'lucide-react';
import api from '../services/api';

/* ════════════════════════════════════════════════
   STYLE INSPIRÉ PAR ONYONO (Pure White & Minimal)
════════════════════════════════════════════════ */

export default function Landing() {
  const navigate = useNavigate();
  const [scrolled, setScrolled] = useState(false);
  const [topProfs, setTopProfs] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    
    // Fetch des profs
    api.get('/api/professeurs/').then(res => {
      const valid = (res.data || []).filter(p => p.statut_validation === 'validé').slice(0, 4);
      setTopProfs(valid);
    }).catch(() => {});

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen bg-white text-[#1a1a1a] selection:bg-black selection:text-white" style={{ fontFamily: '"Inter", sans-serif' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600&display=swap');
        
        .letter-spacing-extra { letter-spacing: 0.2em; }
        .thin-border { border: 1px solid #f0f0f0; }
        
        input:focus { outline: none; }
        
        /* Animation de soulignement comme Onyono */
        .link-underline {
          position: relative;
          display: inline-block;
        }
        .link-underline::after {
          content: '';
          position: absolute;
          width: 100%;
          transform: scaleX(0);
          height: 1px;
          bottom: -2px;
          left: 0;
          background-color: currentColor;
          transform-origin: bottom right;
          transition: transform 0.4s cubic-bezier(0.86, 0, 0.07, 1);
        }
        .link-underline:hover::after {
          transform: scaleX(1);
          transform-origin: bottom left;
        }
      `}</style>

      {/* ─── NAVIGATION (Pure Onyono Style) ─── */}
      <nav className={`fixed w-full z-50 transition-all duration-700 px-6 md:px-12 ${scrolled ? 'bg-white py-4 border-b border-gray-100' : 'bg-transparent py-8'}`}>
        <div className="max-w-[1800px] mx-auto flex justify-between items-center">
          <div className="flex items-center gap-12">
            <h1 className="text-xl font-light tracking-[0.3em] uppercase cursor-pointer" onClick={() => window.scrollTo(0,0)}>
              EduMatch
            </h1>
            <div className="hidden lg:flex gap-8 text-[10px] uppercase tracking-[0.2em] font-medium">
              <button onClick={() => navigate('/profs')} className="link-underline">Formateurs</button>
              <button className="link-underline">À propos</button>
              <button className="link-underline">Contact</button>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <Search size={18} strokeWidth={1.2} className="cursor-pointer hover:opacity-50 transition" />
            <div className="hidden md:flex gap-6 text-[10px] uppercase tracking-[0.2em]">
              <button onClick={() => navigate('/login')} className="link-underline">Connexion</button>
              <button onClick={() => navigate('/register')} className="font-bold">S'inscrire</button>
            </div>
            <Menu size={20} strokeWidth={1.2} className="lg:hidden cursor-pointer" />
          </div>
        </div>
      </nav>

      {/* ─── HERO SECTION ─── */}
      <section className="relative h-screen flex items-center justify-center overflow-hidden bg-[#f9f9f9]">
        <div className="absolute inset-0 z-0">
          <img 
            src="https://images.unsplash.com/photo-1523240795612-9a054b0db644?q=80&w=2070" 
            className="w-full h-full object-cover opacity-[0.15] grayscale" 
            alt="Hero background"
          />
        </div>
        
        <div className="relative z-10 text-center px-4">
          <motion.span 
            initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1 }}
            className="text-[10px] uppercase tracking-[0.5em] text-gray-500 mb-8 block"
          >
            L'excellence académique & professionnelle
          </motion.span>
          
          <motion.h2 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1, delay: 0.3 }}
            className="text-5xl md:text-8xl font-extralight tracking-tighter leading-none mb-12"
          >
            Apprenez sans <br />
            <span className="italic font-serif">compromis.</span>
          </motion.h2>

          <motion.form 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1, delay: 0.6 }}
            onSubmit={(e) => { e.preventDefault(); navigate(`/profs?q=${search}`); }}
            className="flex max-w-xl mx-auto border-b border-black py-2"
          >
            <input 
              type="text" 
              placeholder="Rechercher une matière..." 
              className="bg-transparent w-full text-sm uppercase tracking-widest placeholder:text-gray-300"
              onChange={(e) => setSearch(e.target.value)}
            />
            <button type="submit">
              <ArrowRight size={20} strokeWidth={1} />
            </button>
          </motion.form>
        </div>

        {/* Scroll Indicator */}
        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4">
          <div className="w-[1px] h-12 bg-gray-200"></div>
          <span className="text-[8px] uppercase tracking-[0.3em] text-gray-400">Défiler</span>
        </div>
      </section>

      {/* ─── GRID DE FORMATEURS (Product Style) ─── */}
      <section className="py-32 px-6 md:px-12 max-w-[1600px] mx-auto">
        <div className="flex justify-between items-end mb-16 px-2">
          <div>
            <h3 className="text-[10px] uppercase tracking-[0.3em] text-gray-400 mb-2">Sélection</h3>
            <h2 className="text-2xl font-light uppercase tracking-widest">Nos Mentors</h2>
          </div>
          <button onClick={() => navigate('/profs')} className="text-[10px] uppercase tracking-widest border-b border-black pb-1 hover:opacity-50 transition">
            Tout voir
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-x-8 gap-y-16">
          {topProfs.map((p, i) => (
            <motion.div 
              key={i}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="group cursor-pointer"
              onClick={() => navigate('/login')}
            >
              <div className="aspect-[3/4] bg-[#f5f5f5] overflow-hidden relative mb-6">
                <img 
                  src={p.photo_url ? `http://localhost:8001${p.photo_url}` : "https://via.placeholder.com/600x800?text=Mentor"} 
                  className="w-full h-full object-cover transition-transform duration-[1.5s] group-hover:scale-105 grayscale-[0.5] group-hover:grayscale-0"
                  alt={p.user_nom}
                />
                <div className="absolute top-4 left-4 bg-white px-2 py-1 text-[8px] uppercase tracking-widest font-bold">
                  Premium
                </div>
              </div>
              <div className="flex justify-between items-start px-1">
                <div>
                  <h4 className="text-[11px] uppercase tracking-[0.15em] font-medium">{p.user_prenom} {p.user_nom}</h4>
                  <p className="text-[10px] text-gray-400 mt-1 uppercase tracking-wider italic">
                    {p.tarifs_matieres?.[0]?.nom_matiere || 'Expert'}
                  </p>
                </div>
                <span className="text-[11px] font-light">
                  {p.tarif_en_ligne || p.tarif_presentiel} DT<span className="text-[9px] text-gray-400">/H</span>
                </span>
              </div>
            </motion.div>
          ))}
        </div>
      </section>

      {/* ─── SECTION FEATURES (Minimalist Tiles) ─── */}
      <section className="bg-[#fcfcfc] py-32 px-6 md:px-12 border-y border-gray-50">
        <div className="max-w-[1400px] mx-auto grid grid-cols-1 md:grid-cols-3 gap-24">
          {[
            { title: "Matching IA", desc: "Notre algorithme trouve le mentor parfait selon vos objectifs précis.", icon: <Globe size={24} strokeWidth={1} /> },
            { title: "Liberté totale", desc: "En ligne ou en présentiel. Réservez et apprenez à votre propre rythme.", icon: <BookOpen size={24} strokeWidth={1} /> },
            { title: "Qualité certifiée", desc: "Chaque formateur est rigoureusement validé par nos experts.", icon: <Star size={24} strokeWidth={1} /> }
          ].map((f, i) => (
            <div key={i} className="text-center flex flex-col items-center">
              <div className="mb-8 text-gray-400">{f.icon}</div>
              <h3 className="text-[11px] uppercase tracking-[0.3em] font-bold mb-4">{f.title}</h3>
              <p className="text-xs text-gray-400 leading-relaxed max-w-xs uppercase tracking-widest font-light">
                {f.desc}
              </p>
            </div>
          ))}
        </div>
      </section>

      {/* ─── FOOTER (Pure Onyono Style) ─── */}
      <footer className="py-24 px-6 md:px-12 bg-white">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between gap-16 border-t border-gray-100 pt-16">
          <div className="max-w-xs">
            <h2 className="text-sm tracking-[0.4em] uppercase mb-8">EduMatch</h2>
            <p className="text-[10px] text-gray-400 leading-relaxed uppercase tracking-widest italic">
              Redéfinir l'apprentissage académique par l'élégance et la technologie.
            </p>
          </div>
          
          <div className="grid grid-cols-2 gap-20">
            <div className="flex flex-col gap-4">
              <span className="text-[9px] uppercase tracking-[0.3em] font-bold text-gray-300 mb-2">Navigation</span>
              {['Profs', 'Cours', 'À propos'].map(link => (
                <a key={link} className="text-[10px] uppercase tracking-widest hover:opacity-50 transition cursor-pointer">{link}</a>
              ))}
            </div>
            <div className="flex flex-col gap-4">
              <span className="text-[9px] uppercase tracking-[0.3em] font-bold text-gray-300 mb-2">Légal</span>
              {['Confidentialité', 'Mentions', 'Cookies'].map(link => (
                <a key={link} className="text-[10px] uppercase tracking-widest hover:opacity-50 transition cursor-pointer">{link}</a>
              ))}
            </div>
          </div>

          <div className="min-w-[300px]">
            <span className="text-[9px] uppercase tracking-[0.3em] font-bold text-gray-300 mb-6 block">Newsletter</span>
            <div className="flex border-b border-black pb-2">
              <input type="text" placeholder="VOTRE EMAIL" className="text-[10px] w-full bg-transparent outline-none tracking-widest" />
              <button className="text-[10px] font-bold tracking-widest">OK</button>
            </div>
          </div>
        </div>
        
        <div className="max-w-[1600px] mx-auto mt-24 flex justify-between items-center text-[8px] uppercase tracking-[0.4em] text-gray-300">
          <p>© 2024 EDUMATCH TUNISIA</p>
          <p>DÉVELOPPÉ AVEC RIGUEUR</p>
        </div>
      </footer>
    </div>
  );
}
